vector<vector<Mint>> operator * (vector<vector<Mint>> a, vector<vector<Mint>> b) {
    vector<vector<Mint>> c(a.size(), vector<Mint>(b[0].size(), 0));
    for (int i = 0; i < a.size(); ++i) {
        for (int j = 0; j < a[0].size(); ++j) {
            for (int k = 0; k < b[0].size(); ++k) {
                c[i][k] += a[i][j] * b[j][k];
            }
        }
    }
    return c;
}

vector<vector<Mint>> pow(vector<vector<Mint>> a, ll p) {
    vector<vector<Mint>> res(a.size(), vector<Mint>(a.size(), 0));
    for (int i = 0; i < res.size(); ++i) {
        res[i][i] = 1;
    }
    while (p) {
        if (p & 1) {
            res = res * a;
        }
        a = a * a;
        p /= 2;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    ll n;
    cin >> n;
    int k;
    cin >> k;

    vector<vector<Mint>> mt((k + 1) * 2 + 1, vector<Mint>((k + 1) * 2 + 1, 0));

    vector<vector<Mint>> vinit(mt.size(), vector<Mint>(1, 0));

    // first k+1 elements are for F_{i-1}, next k+1 are for F_{i-2}, the last one is for sum up to A_{i-2}
    for (int i = 0; i < k + 1; ++i) {
        vinit[i][0] = 1;
        vinit[i + k + 1][0] = 0;
        vinit.back()[0] = 0;
    }
    vinit[k + 1][0] = 1;

    vector<vector<Mint>> C(50, vector<Mint>(50, 0));
    for (int i = 0; i < C.size(); ++i) {
        C[0][i] = 0;
        C[i][0] = 1;
    }

    for (int i = 1; i < C.size(); ++i) {
        for (int j = 1; j < C.size(); ++j) {
            C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
        }
    }

    vector<Mint> p2(50, 1);
    for (int i = 1; i < p2.size(); ++i)
        p2[i] = p2[i - 1] * 2;

    for (int p = 0; p < k + 1; ++p)
        mt[k + 1 + p][p] = 1;
    mt.back().back() = 1;
    mt.back()[k] = 1;

    for (int p = 0; p < k + 1; ++p) {
        for (int j = 0; j <= p; ++j) {
            mt[p][j] += C[p][j];
            mt[p][k + 1 + j] += C[p][j] * p2[p - j];
        }
    }

    auto res = pow(mt, n) * vinit;
    cout << res.back()[0] << '\n';

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    int n;
    cin >> n;
    vector<int> a(n), b(n), c(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    for (int i = 0; i < n; ++i)
        cin >> b[i];
    for (int i = 0; i < n; ++i)
        cin >> c[i];

    for (auto k : c) {
        b.push_back(k);
    }

    map<int, int> whereb;
    map<int, int> wherec;
    for (int i = (int)b.size() - 1; i >= 0; --i)
        whereb[b[i]] = i;
    for (int i = (int)c.size() - 1; i >= 0; --i)
        wherec[c[i]] = i;

    vector<bool> first_in_a(a.size(), false);
    vector<bool> first_in_b(b.size(), false);
    set<int> ina, inb;
    for (int i = 0; i < a.size(); ++i) {
        if (!ina.count(a[i])) {
            ina.insert(a[i]);
            first_in_a[i] = true;
        }
    }
    for (int i = 0; i < b.size(); ++i) {
        if (!inb.count(b[i])) {
            inb.insert(b[i]);
            first_in_b[i] = true;
        }
    }

    set<pair<int, int>> maxs;
    multiset<int> res;

    maxs.emplace(1e9, 0);
    maxs.emplace(-1, 1e9 + 5);
    res.insert(maxs.begin()->first + next(maxs.begin())->second + 1);

    auto del = [&](pair<int, int> p) {
        auto it = maxs.find(p);
        assert(it != maxs.end());
        auto inext = next(it);
        auto iprev = prev(it);

        res.erase(res.find(iprev->first + it->second + 1));
        res.erase(res.find(it->first + inext->second + 1));
        maxs.erase(it);
        res.insert(iprev->first + inext->second + 1);
    };

    auto add = [&](pair<int, int> p) {
        auto it = maxs.lower_bound(make_pair(p.first, -5));
        if (it->second >= p.second) return;
        if (it->first == p.first) {
            ++it;
        }
        while (prev(it)->second <= p.second)
            del(*prev(it));

        maxs.insert(p);
        it = maxs.find(p);
        auto inext = next(it);
        auto iprev = prev(it);

        res.insert(iprev->first + it->second + 1);
        res.insert(it->first + inext->second + 1);
        res.erase(res.find(iprev->first + inext->second + 1));
    };

    for (int i = 0; i < b.size(); ++i) {
        if (first_in_b[i] && !ina.count(b[i])) {
            int inc = 1e9;
            if (wherec.count(b[i]))
                inc = wherec[b[i]] + 1;
            add({i, inc});
        }
    }

    int ans = n + *res.begin();

    for (int i = n - 1; i >= 0; --i) {
        if (first_in_a[i]) {
            if (!inb.count(a[i])) break;
            int inc = 1e9;
            if (wherec.count(a[i]))
                inc = wherec[a[i]] + 1;
            add({whereb[a[i]], inc});
        }
        ans = min(ans, i + *res.begin());
    }

    cout << ans << '\n';

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define ll long long

const int inf = 1e9;

int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    int n;
    cin >> n;
    vector<int> v(n);
    for (int i = 0; i < n; ++i) {
        cin >> v[i];
    }

    v.insert(v.begin(), 0);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < i; ++j) {
            v[i] = max(v[i], v[j] + v[i - j]);
        }
    }

    vector<int> w(n);
    for (int i = 0; i < n; ++i) {
        cin >> w[i];
    }

    auto getv = [&](int ln) {
        if (ln < v.size()) return v[ln];
        return -inf;
    };

    vector<vector<ll>> dp_all(n, vector<ll>(n, -inf));
    vector<vector<ll>> dp_mon(n, vector<ll>(n, -inf));
    vector<vector<ll>> dp(n, vector<ll>(n, 0));

    for (int i = 0; i < n; ++i) {
        dp_mon[i][i] = 0;
        dp_all[i][i] = v[1];
        if (i != 0)
            dp_all[i][i - 1] = 0;
    }

    for (int k = 1; k <= n; ++k) {
        for (int l = 0; l < n; ++l) {
            int r = l + k - 1;
            if (r >= n) break;

            for (int j = l + 1; j <= r; ++j) {
                dp_all[l][r] = max(dp_all[l][r], dp_all[l][j - 1] + dp_all[j][r]);
            }

            if (w[l] != w[r]) {
                if (abs(w[l] - w[r]) == 1) {
                    dp_mon[l][r] = dp_all[l + 1][r - 1];
                } else {
                    for (int j = l + 1; j < r; ++j) {
                        if (w[l] != w[j] && w[r] != w[j] && ((w[l] < w[j]) == (w[j] < w[r]))) {
                            dp_mon[l][r] = max(dp_mon[l][r], dp_mon[l][j] + dp_mon[j][r]);
                        }
                    }
                }
            }

            for (int j = l; j <= r; ++j)
                if (w[j] >= w[l] && w[j] >= w[r])
                    dp_all[l][r] = max(dp_all[l][r], dp_mon[l][j] + dp_mon[j][r] + getv(abs(w[l] - w[j]) + abs(w[j] - w[r]) + 1));

            dp[l][r] = max(dp[l][r], dp_all[l][r]);
            for (int j = l + 1; j <= r; ++j)
                dp[l][r] = max(dp[l][r], dp[l][j - 1] + dp[j][r]);
        }
    }

    cout << dp[0][n - 1] << '\n';

    return 0;
}
